function renderLogin() {
  const html = `
    <div class="login-container">
      <div class="login-card">
        <div class="login-logo" style="text-align: center;">
          <img src="data:image/png;base64," alt="固润科技" style="max-width: 280px; width: 100%; height: auto; margin-bottom: 16px;">
          <h1 style="font-size: 24px; margin: 0;">工程项目管理系统</h1>
        </div>
        
        <form id="loginForm" class="login-form">
          <div class="form-group">
            <label class="form-label">用户名</label>
            <input type="text" id="username" class="form-input" placeholder="请输入用户名" required value="admin">
          </div>
          
          <div class="form-group">
            <label class="form-label">密码</label>
            <input type="password" id="password" class="form-input" placeholder="请输入密码" required>
          </div>
          
          <div class="form-group form-check">
            <input type="checkbox" id="rememberMe" class="form-check-input">
            <label for="rememberMe" class="form-check-label">记住我</label>
          </div>
          
          <button type="submit" class="btn btn-primary btn-block" id="loginBtn">
            <i class="fas fa-sign-in-alt"></i>
            登录
          </button>
        </form>
        
        <div class="login-footer">
          <p>默认账号: <span class="password-hint">admin / 123456</span></p>
        </div>
      </div>
      
      <div class="login-bg-decoration">
        <div class="bg-circle bg-circle-1"></div>
        <div class="bg-circle bg-circle-2"></div>
        <div class="bg-circle bg-circle-3"></div>
      </div>
    </div>
  `;
  
  document.body.innerHTML = html;
  attachLoginEvents();
}

function attachLoginEvents() {
  const form = document.getElementById('loginForm');
  
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    
    const username = document.getElementById('username').value.trim();
    const password = document.getElementById('password').value;
    
    if (!username || !password) {
      showLoginError('请输入用户名和密码');
      return;
    }
    
    const success = store.login(username, password);
    
    if (success) {
      showLoginSuccess();
      setTimeout(() => {
        initApp();
      }, 1500);
    } else {
      showLoginError('用户名或密码错误');
    }
  });
}

function showLoginError(message) {
  const errorDiv = document.createElement('div');
  errorDiv.className = 'alert alert-danger';
  errorDiv.textContent = message;
  errorDiv.style.marginBottom = '16px';
  
  const loginCard = document.querySelector('.login-card');
  loginCard.insertBefore(errorDiv, loginCard.firstChild);
  
  setTimeout(() => {
    errorDiv.remove();
  }, 3000);
}

function showLoginSuccess() {
  const successDiv = document.createElement('div');
  successDiv.className = 'alert alert-success';
  successDiv.textContent = '登录成功，正在进入系统...';
  successDiv.style.marginBottom = '16px';
  
  const loginCard = document.querySelector('.login-card');
  loginCard.insertBefore(successDiv, loginCard.firstChild);
}

function initApp() {
  // 恢复页面初始HTML结构
  document.body.innerHTML = `
    <div class="layout">
      <aside class="sidebar" id="sidebar">
      </aside>
      
      <div class="sidebar-overlay"></div>
      
      <main class="main-content">
        <header class="header" id="header">
        </header>
        
        <div id="content">
        </div>
      </main>
    </div>
  `;
  
  // 应用暗黑模式
  const isDarkMode = store.getState().darkMode;
  if (isDarkMode) {
    document.body.classList.add('dark-mode');
  }
  
  // 初始化路由
  router.init();
  
  // 渲染初始内容
  renderSidebar();
  renderHeader();
  renderContent();
}
